    if dst_md.exists():
        dst_fm, _ = split_frontmatter(dst_md.read_text())
        dst_fm = dst_fm or {}

    new_fm = dict(src_fm)
    if isinstance(new_fm.get("description"), str):
        new_fm["description"] = new_fm["description"].strip()
